/* Sem cena escrita (magias criadas por você): escolhe a que mais combina com o texto. */
const CENA_PISTAS = [
  [/meteor/, 'meteor-swarm'], [/terremoto|earthquake|tremor/, 'earthquake'], [/explo|fireball|bola de fogo/, 'fireball'], [/rel[aâ]mpago|el[eé]tric|lightning/, 'lightning-bolt'], [/trov[aã]o|thunder|estrondo/, 'thunderwave'],
  [/gelo|frio|neve|ice|cold|frost/, 'cone-of-cold'], [/veneno|poison|t[oó]xic/, 'stinking-cloud'], [/[aá]cido|acid/, 'acid-splash'], [/teleport|dimens|portal/, 'misty-step'], [/m[aã]os?\b|hand/, 'mage-hand'],
  [/escudo|shield|barreira|prote[cç]/, 'shield'], [/invis[ií]vel|invisib/, 'invisibility'], [/ilus[aã]o|illus/, 'minor-illusion'], [/medo|pavor|fear/, 'fear'], [/encant|charm|fascin/, 'charm-person'], [/sono|sleep|dormir/, 'sleep'],
  [/nuvem|n[eé]voa|fog|cloud/, 'fog-cloud'], [/muralha|parede|wall/, 'wall-of-stone'], [/planta|vinha|raiz|vine|root/, 'entangle'], [/corrente|preso|paralis|chain|hold/, 'hold-person'], [/espada|l[aâ]mina|sword|blade/, 'spiritual-weapon'],
  [/flecha|arrow/, 'acid-arrow'], [/invoc|conjur|summon/, 'find-familiar'], [/[aá]gua|water|onda/, 'control-water'], [/escurid|sombra|dark|shadow/, 'darkness'], [/luz|sol|radian|light/, 'daylight'], [/morte|necr|morto|death/, 'inflict-wounds'], [/fogo|chama|fire|flame/, 'fire-bolt']
];
function cenaSugerida(s) {
  const cura = (s.r || []).some(x => x.heal && x.t === 'dmg'), dano = (s.r || []).some(x => x.t === 'dmg' && !x.heal), ataque = (s.r || []).some(x => x.t === 'atk');
  if (cura && !dano) return ['amanhecer:cura', '', ...CENAS['cure-wounds'].slice(2)];
  const texto = norm(`${s.name} ${s.en || ''} ${(s.desc || []).join(' ')}`), pista = CENA_PISTAS.find(([re]) => re.test(texto) || re.test(`${s.name} ${(s.desc || []).join(' ')}`.toLowerCase()));
  if (pista) return [CENAS[pista[1]][0], '', ...CENAS[pista[1]].slice(2)];
  if (dano && ataque) return ['arcano', '', ['lancar', { s: .09, voo: .55 }], ['explodir', { t: [.55, 1] }]];
  if (dano) return ['arcano', '', ['explodir', { t: [.3, 1] }], ['ondas', { em: 'B', s: .8 }]];
  return ['arcano', '', ['runas', { em: 'C', s: .4 }], ['aura', { em: 'C', s: .3 }]];
}
const cenaSlug = s => norm(s.en || '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
function cenaDe(s) {
  if (Array.isArray(s.cena)) return s.cena;
  return CENAS[s.cena] || CENAS[s.id] || CENAS[cenaSlug(s)] || cenaSugerida(s);
}
